    if (capacity == 0) return NULL;
    ringbuf_t *rb = malloc(sizeof(ringbuf_t));
    if (!rb) return NULL;
    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) { free(rb); return NULL; }
    rb->sz = 0;
    rb->cap = capacity;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (rb == NULL) return;
    free(rb->buf);
    free(rb);
}

static size_t rb_free(const ringbuf_t *rb) {
    return rb->cap - rb->sz;
