size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!_rb_is_valid(rb) || data == NULL || len == 0) return 0;
    size_t free_space = rb_free(rb);
    size_t to_write = len < free_space ? len : free_space;
    /* split into two writes for wrap-around */
    size_t headroom = rb->cap - (rb->sz + rb->head) % rb->cap;
